package vn.edu.eaut.lab6.controller; import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import vn.edu.eaut.lab6.model.Student;import vn.edu.eaut.lab6.store.StudentStore;@WebServlet("/student-edit") public class EditStudentServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Student s=StudentStore.findById(q.getParameter("id"));if(s==null){p.sendRedirect(q.getContextPath()+"/students");return;}q.setAttribute("student",s);q.getRequestDispatcher("/student-edit.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{q.setCharacterEncoding("UTF-8");Student s=new Student(q.getParameter("id"),q.getParameter("name"),q.getParameter("className"),q.getParameter("email"));StudentStore.update(s);p.sendRedirect(q.getContextPath()+"/students");}}
